import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/Home'; // Reusing Home styles for simplified about in this demo
import Products from './pages/Products';
import Dao from './pages/Dao';
import Investors from './pages/Investors';
import Contact from './pages/Contact';
import { LanguageProvider } from './context/LanguageContext';

const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<string>(() => {
    return window.location.hash.replace('#', '') || '/';
  });

  useEffect(() => {
    const handleHashChange = () => {
      setCurrentRoute(window.location.hash.replace('#', '') || '/');
      window.scrollTo(0, 0);
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const renderRoute = () => {
    if (currentRoute === '/') return <Home />;
    if (currentRoute === '/products') return <Products />;
    if (currentRoute === '/dao') return <Dao />;
    if (currentRoute === '/about') return <Home />; // In a full app, this would be About page
    if (currentRoute === '/investors') return <Investors />;
    if (currentRoute === '/contact') return <Contact />;
    if (currentRoute === '/docs') return <div className="pt-32 pb-20 text-center text-zinc-500">Docs coming soon...</div>;
    return <Home />;
  };

  return (
    <LanguageProvider>
      <div className="min-h-screen flex flex-col selection:bg-cyan-500/30">
        <Navbar />
        <main className="flex-grow">
          {renderRoute()}
        </main>
        <Footer />
      </div>
    </LanguageProvider>
  );
};

export default App;

