import { ArrowRight, Bot, Activity, Zap, Shield, Globe, Cpu } from 'lucide-react';
import { motion, useScroll, useTransform, useSpring, useMotionValue } from 'framer-motion';

const HeroBackground = () => {
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const handleMouseMove = (e: React.MouseEvent) => {
    const { clientX, clientY } = e;
    mouseX.set(clientX);
    mouseY.set(clientY);
  };

  // Smoothed mouse positions for subtle parallax
  const smoothX = useSpring(mouseX, { damping: 50, stiffness: 400 });
  const smoothY = useSpring(mouseY, { damping: 50, stiffness: 400 });

  // Parallax transforms for background layers
  const rotateX = useTransform(smoothY, [0, 1000], [2, -2]);
  const rotateY = useTransform(smoothX, [0, 2000], [-2, 2]);

  return (
    <div 
      className="absolute inset-0 overflow-hidden pointer-events-none select-none"
      onMouseMove={handleMouseMove}
    >
      {/* Interactive Interactive Glow Layer */}
      <motion.div
        className="absolute w-[800px] h-[800px] rounded-full bg-cyan-500/5 blur-[120px] z-0"
        style={{
          x: useTransform(smoothX, (val) => val - 400),
          y: useTransform(smoothY, (val) => val - 400),
        }}
      />

      {/* Layer 1: The Deep Grid */}
      <motion.div 
        style={{ rotateX, rotateY, perspective: 1000 }}
        className="absolute inset-0 z-0"
      >
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#00f3ff08_1px,transparent_1px),linear-gradient(to_bottom,#00f3ff08_1px,transparent_1px)] bg-[size:80px_80px]" />
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,#00f3ff05_1px,transparent_1px)] bg-[size:20px_20px]" />
      </motion.div>

      {/* Layer 2: Vertical Data Streams (AI Logic Flows) */}
      <div className="absolute inset-0 flex justify-around opacity-20">
        {[...Array(12)].map((_, i) => (
          <motion.div
            key={`v-stream-${i}`}
            className="w-[1px] h-full bg-gradient-to-b from-transparent via-cyan-400/50 to-transparent relative"
            initial={{ opacity: 0 }}
            animate={{ opacity: [0.1, 0.4, 0.1] }}
            transition={{ duration: Math.random() * 5 + 3, repeat: Infinity }}
          >
             <motion.div
                className="absolute top-0 left-[-2px] w-[5px] h-20 bg-gradient-to-b from-cyan-400 to-transparent"
                animate={{ top: ["-10%", "110%"] }}
                transition={{ 
                  duration: Math.random() * 3 + 2, 
                  repeat: Infinity, 
                  ease: "linear",
                  delay: Math.random() * 5
                }}
             />
          </motion.div>
        ))}
      </div>

      {/* Layer 3: Floating Data Packets (Binary fragments) */}
      <div className="absolute inset-0">
        {[...Array(15)].map((_, i) => (
          <motion.div
            key={`packet-${i}`}
            className="absolute text-[8px] font-mono text-cyan-500/40 whitespace-nowrap"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              y: [0, -100],
              opacity: [0, 1, 0],
              x: [0, (Math.random() - 0.5) * 50]
            }}
            transition={{
              duration: Math.random() * 10 + 10,
              repeat: Infinity,
              ease: "linear",
              delay: Math.random() * 20
            }}
          >
            {Math.random() > 0.5 ? '01101011' : '0xFFFF'}
          </motion.div>
        ))}
      </div>

      {/* Layer 4: Geometric Clusters (Nodes) */}
      <div className="absolute inset-0 z-10">
        {[...Array(6)].map((_, i) => (
          <motion.div
            key={`cluster-${i}`}
            className="absolute"
            style={{
              left: `${15 + i * 15}%`,
              top: `${20 + (i % 3) * 20}%`,
            }}
            animate={{
              y: [0, -20, 0],
              rotate: [0, 5, 0]
            }}
            transition={{
              duration: 8 + i,
              repeat: Infinity,
              ease: "easeInOut"
            }}
          >
            <div className="relative group">
              <div className="w-2 h-2 bg-cyan-500 rounded-sm shadow-[0_0_15px_rgba(0,243,255,0.6)]" />
              <svg className="absolute top-[-24px] left-[-24px] w-12 h-12 overflow-visible">
                <motion.circle 
                  cx="24" cy="24" r="18" 
                  fill="none" 
                  stroke="currentColor" 
                  strokeWidth="0.5" 
                  className="text-cyan-500/20"
                  animate={{ r: [18, 22, 18], opacity: [0.2, 0.5, 0.2] }}
                  transition={{ duration: 4, repeat: Infinity }}
                />
                <motion.path 
                  d="M 24 6 L 24 0 M 24 42 L 24 48 M 6 24 L 0 24 M 42 24 L 48 24" 
                  stroke="currentColor" 
                  strokeWidth="1"
                  className="text-cyan-500/40"
                />
              </svg>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Scanning Laser Beam (Horizontal) */}
      <motion.div 
        className="absolute w-full h-[2px] bg-gradient-to-r from-transparent via-cyan-400/20 to-transparent z-10"
        animate={{ top: ["10%", "90%", "10%"] }}
        transition={{ duration: 20, repeat: Infinity, ease: "easeInOut" }}
      />
    </div>
  );
};

