        {[...Array(40)].map((_, i) => (
          <motion.div
            key={`dot-${i}`}
            className="absolute w-1 h-1 bg-cyan-500/20 rounded-full"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              scale: [1, 1.5, 1],
              opacity: [0.1, 0.4, 0.1],
            }}
            transition={{
              duration: 3 + Math.random() * 5,
              repeat: Infinity,
              ease: "easeInOut",
              delay: Math.random() * 5
            }}
          />
        ))}
      </motion.div>

      {/* Layer 4: Vertical Logical Pulses */}
      <div className="absolute inset-0 flex justify-around opacity-10 dark:opacity-30">
        {[...Array(15)].map((_, i) => (
          <div key={`col-${i}`} className="w-[1px] h-full relative">
