  Zap, 
  Layers, 
  Globe, 
  Cpu, 
  ArrowLeft, 
  ChevronRight, 
  ShieldCheck, 
  Code,
  Terminal,
  ExternalLink,
  LineChart as LineChartIcon,
  TrendingUp,
  RefreshCw
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  ReferenceLine
} from 'recharts';

interface ProductDetailProps {
  slug: string;
}

const ProductDetail: React.FC<ProductDetailProps> = ({ slug }) => {
  const { t } = useLanguage();
  const product = PRODUCTS.find(p => p.slug === slug);

  // Initialize and manage real-time chart data
  const baseValue = useMemo(() => {
    if (!product) return 0;
    const slug = product.slug;
    if (slug === 'microbot') return 5000;
    if (slug === 'nexus') return 94.2;
    if (slug === 'onlyvips') return 120;
    if (slug === 'arayis') return 65;
    if (slug === 'transfer') return 450;
    return 100;
  }, [product]);

  const [chartData, setChartData] = useState<{time: string, value: number}[]>([]);

  // Initial data generation
  useEffect(() => {
    const initialData = [];
    const now = new Date();
    for (let i = 20; i >= 0; i--) {
      const time = new Date(now.getTime() - i * 5000);
      const fluctuation = Math.random() * (baseValue * 0.1) - (baseValue * 0.05);
      initialData.push({
        time: time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        value: Math.floor((baseValue + fluctuation) * 10) / 10
      });
    }
    setChartData(initialData);
  }, [baseValue]);

  // Real-time update simulation
  useEffect(() => {
    const interval = setInterval(() => {
      setChartData(prev => {
        const newData = [...prev];
        const lastTime = new Date();
        const fluctuation = Math.random() * (baseValue * 0.1) - (baseValue * 0.05);
        newData.shift();
        newData.push({
          time: lastTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          value: Math.floor((baseValue + fluctuation) * 10) / 10
        });
        return newData;
      });
    }, 3000);
    return () => clearInterval(interval);
  }, [baseValue]);

  const metricLabel = useMemo(() => {
    switch(product?.slug) {
      case 'microbot': return { en: 'Max Throughput (TPS)', tr: 'Maks. İşlem Hızı (TPS)', ru: 'Макс. пропускная способность (TPS)' };
      case 'nexus': return { en: 'Detection Accuracy (%)', tr: 'Tespit Doğruluğu (%)', ru: 'Точность обнаружения (%)' };
      case 'onlyvips': return { en: 'Daily Access Auth', tr: 'Günlük Erişim Yetkisi', ru: 'Суточная авторизация' };
      case 'arayis': return { en: 'Asset Discovery Index', tr: 'Varlık Keşif Endeksi', ru: 'Индекс поиска активов' };
      case 'transfer': return { en: 'Bridged Liquidity (M$)', tr: 'Köprülenen Likidite (M$)', ru: 'Ликвидность моста (M$)' };
      default: return { en: 'Performance Index', tr: 'Performans Endeksi', ru: 'Индекс производительности' };
    }
  }, [product]);

  if (!product) {
