                onClick={() => setIsOpen(false)}
                className="block px-3 py-4 text-lg font-medium text-zinc-500 dark:text-zinc-400 hover:text-cyan-400 border-b border-black/5 dark:border-white/5"
              >
                {t(item.label)}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

